<?php
require_once __DIR__ . '/../../includes/auth.php';requireLogin();if(!hasRole('admin')){http_response_code(403);die('Relatório de ponto restrito ao administrador.');}require_once __DIR__ . '/../../includes/header.php';$db=getDB();$de=$_GET['de']??date('Y-m-01');$ate=$_GET['ate']??date('Y-m-d');$usuario=(int)($_GET['usuario_id']??0);$usuarios=$db->query("SELECT id,nome FROM usuarios WHERE ativo=1 ORDER BY nome")->fetchAll();$where='r.data BETWEEN ? AND ?';$params=[$de,$ate];if($usuario){$where.=' AND r.usuario_id=?';$params[]=$usuario;}$st=$db->prepare("SELECT r.*,u.nome FROM registros_ponto r JOIN usuarios u ON u.id=r.usuario_id WHERE $where ORDER BY u.nome,r.data");$st->execute($params);$registros=$st->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['horas_trabalhadas'],$registros));
?>
<div class="page-header"><div class="page-title"><i class="fa-solid fa-clipboard-list"></i> Relatório de ponto</div><button class="btn btn-outline" onclick="window.print()"><i class="fa-solid fa-print"></i> Imprimir</button></div><div class="card"><div class="card-body"><form method="GET" class="form-row cols-4"><div class="form-group"><label>Funcionário</label><select name="usuario_id"><option value="0">Todos</option><?php foreach($usuarios as $u):?><option value="<?= $u['id'] ?>" <?= $usuario===$u['id']?'selected':'' ?>><?= htmlspecialchars($u['nome']) ?></option><?php endforeach;?></select></div><div class="form-group"><label>De</label><input type="date" name="de" value="<?= htmlspecialchars($de) ?>"></div><div class="form-group"><label>Até</label><input type="date" name="ate" value="<?= htmlspecialchars($ate) ?>"></div><div><button class="btn btn-primary"><i class="fa-solid fa-filter"></i> Filtrar</button></div></form></div></div><div class="grid-3"><div class="kpi-card"><div><div class="kpi-label">REGISTROS</div><div class="kpi-value"><?= count($registros) ?></div></div></div><div class="kpi-card green"><div><div class="kpi-label">HORAS REGISTRADAS</div><div class="kpi-value"><?= number_format($total,2,',','.') ?>h</div></div></div><div class="kpi-card yellow"><div><div class="kpi-label">PERÍODO</div><div class="kpi-value" style="font-size:17px"><?= date('d/m/Y',strtotime($de)) ?> a <?= date('d/m/Y',strtotime($ate)) ?></div></div></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Funcionário</th><th>Data</th><th>Entrada 1</th><th>Saída 1</th><th>Entrada 2</th><th>Saída 2</th><th>Entrada 3</th><th>Saída 3</th><th>Horas</th><th>Situação</th></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?= htmlspecialchars($r['nome']) ?></td><td><?= date('d/m/Y',strtotime($r['data'])) ?></td><?php foreach(['entrada1','saida1','entrada2','saida2','entrada3','saida3'] as $f):?><td><?= $r[$f]?substr($r[$f],0,5):'–' ?></td><?php endforeach;?><td><?= number_format((float)$r['horas_trabalhadas'],2,',','.') ?>h</td><td><?= htmlspecialchars(ucfirst(str_replace('_',' ',$r['tipo_dia']))) ?></td></tr><?php endforeach;?><?php if(!$registros):?><tr><td colspan="10" style="text-align:center;padding:35px">Nenhum registro no período.</td></tr><?php endif;?></tbody></table></div></div><?php require_once __DIR__ . '/../../includes/footer.php'; ?>
